 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # A completely empty row is filled by extending the preceding row's color.
    for r, row in enumerate(out):
        if all(v == 0 for v in row) and r > 0:
            previous = out[r - 1]
            colors = [v for v in previous if v != 0]
            if colors and len(set(colors)) == 1:
                out[r] = [colors[0]] * len(row)
