 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Each diagonal running down-right encodes one color at an offset c-r.
    stripes = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                d = c - r
                if d in stripes and stripes[d] != value:
                    raise ValueError('inconsistent diagonal')
                stripes[d] = value
    if not stripes:
        return [row[:] for row in grid]
    # Find the shortest repeating diagonal period consistent with all marked stripes.
    period = 1
    while True:
        by_residue = {}
        valid = True
        for d, color in stripes.items():
            residue = d % period
            if residue in by_residue and by_residue[residue] != color:
                valid = False
                break
            by_residue[residue] = color
        if valid:
            break
        period += 1
    return [[by_residue[(c-r) % period] for c in range(w)] for r in range(h)]
